function makeCounter(start = 0) {
  let count = start;
  return {
    next: () => ++count,
    reset: () => { count = 0; },
    get: () => count,
  };
}
const c = makeCounter(10);
console.log(c.next(), c.next(), c.get()); // 11 12 12

