const Store = {
  get(key, fallback) {
    try { return JSON.parse(localStorage.getItem(key)) ?? fallback; }
    catch { return fallback; }
  },
  set(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); }
    catch (e) { console.warn("Quota exceeded", e); }
  },
};
Store.set("theme", "dark");
console.log(Store.get("theme", "light")); // "dark"

async function getJSON(url, options) {
  const r = await fetch(url, options);
  if (!r.ok) throw new Error(`HTTP ${r.status}: ${r.statusText}`);
  return r.json();
}

try {
  const user = await getJSON("/api/users/1");
  console.log(user);
} catch (err) {
  console.error("Request failed:", err.message);
}

class ApiError extends Error {
  constructor(message, { status, cause } = {}) {
    super(message, { cause });
    this.name = "ApiError";
    this.status = status;
  }
}

async function getUser(id) {
  const r = await fetch(`/api/users/${id}`);
  if (!r.ok) throw new ApiError(`Failed to load user ${id}`, { status: r.status, cause: new Error(`HTTP ${r.status}`) });
  return r.json();
}

try {
  await getUser(999);
} catch (err) {
  if (err instanceof ApiError) console.error(`${err.name} (${err.status}):`, err.message, "caused by", err.cause);
  else throw err;
}

